window.SAOMD_STORIES[410401801]={"id":410401801,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401801:1:1","speaker":"Hel","text":"Mmm, yes, that's it!\nI love strong men!","pose":20410104,"background":"bg_event_fire_cave_boss","item":"","illustration":"","speaker_zh":"赫尔","text_zh":"嗯，对，就是这样！我喜欢坚强的男人！"}]},{"id":2,"order":2,"actions":[{"uid":"410401801:2:1","speaker":"Hel","text":"There's so many hotheaded lunks\nhere too! It's been so much fun!","pose":20410104,"background":"","item":"","illustration":"","speaker_zh":"赫尔","text_zh":"这里也有很多头脑发热的笨蛋！太有趣了！"}]},{"id":3,"order":3,"actions":[{"uid":"410401801:3:1","speaker":"Hel","text":"But you know, the thing I love\nmost is seeing strong men like\nyou crawling before me!","pose":20410104,"background":"","item":"","illustration":"","speaker_zh":"赫尔","text_zh":"但是你知道吗，我最喜欢的就是看到像你这样的强者在我面前爬行！"}]},{"id":4,"order":4,"actions":[{"uid":"410401801:4:1","speaker":"Klein","text":"Gaah! Damn it all...","pose":10080408,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"嘎啊！该死的这一切..."}]},{"id":5,"order":5,"actions":[{"uid":"410401801:5:1","speaker":"Klein","text":"Hel, was it? If you weren't\nattacking us, I might've liked\nto get to know you better.","pose":10080407,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"赫尔，是吗？如果你没有攻击我们，我可能会想更好地了解你。"}]},{"id":6,"order":6,"actions":[{"uid":"410401801:6:1","speaker":"Hel","text":"What are you talking about, worm?\nIf this is what passes for death\nthroes now, count me out.","pose":20410105,"background":"","item":"","illustration":"","speaker_zh":"赫尔","text_zh":"你在说什么啊，虫子？如果现在这就是死亡的痛苦，那就别算我了。"}]},{"id":7,"order":7,"actions":[{"uid":"410401801:7:1","speaker":"Klein","text":"Nah, it's nothing like that.\nI just have a soft spot for ladies\nwho aren't so good with feelings.","pose":100804052,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"不，不是那样的。我只是对那些不太善于感情的女士情有独钟。"}]},{"id":8,"order":8,"actions":[{"uid":"410401801:8:1","speaker":"Hel","text":"I'm done with you.\nHurry up and die.","pose":20410107,"background":"","item":"","illustration":"","speaker_zh":"赫尔","text_zh":"我和你受够了。赶紧去死吧。"}]},{"id":9,"order":9,"actions":[{"uid":"410401801:9:1","speaker":"Klein","text":"Heh heh... Honestly, dying by your\nhand may not be a bad way to go...","pose":100804042,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"呵呵……说实话，死在你手上或许也不错……"}]},{"id":10,"order":10,"actions":[{"uid":"410401801:10:1","speaker":"Leafa","text":"Klein seems to be... doing okay...","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"克莱因看起来……还不错……"}]},{"id":11,"order":11,"actions":[{"uid":"410401801:11:1","speaker":"Asuna","text":"Y-Yeah, I guess...","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是、是啊，我想……"},{"uid":"410401801:11:2","speaker":"Leafa","text":"","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410401801:12:1","speaker":"Klein","text":"Hm? Wha?! When'd you all get\nhere?!","pose":10080408,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"嗯？世界卫生大会？！你们什么时候到的？！"}]},{"id":13,"order":13,"actions":[{"uid":"410401801:13:1","speaker":"Alice","text":"Is he one of your friends, Asuna?\nHe seems to be handling the\nsituation well on his own...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他是你的朋友吗，亚丝娜？看来他自己处理得很好……"},{"uid":"410401801:13:2","speaker":"Leafa","text":"","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:13:3","speaker":"Asuna","text":"","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410401801:14:1","speaker":"Klein","text":"Uh, trust me, I'm really not!\nCan't you see I'm on my last\nlegs?! Please, you gotta help me!","pose":100804082,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"呃，相信我，我真的不是！你没看到我已经只剩下最后一条腿了吗？！拜托，你一定要帮帮我！"}]},{"id":15,"order":15,"actions":[{"uid":"410401801:15:1","speaker":"Asuna","text":"You heard the man...\nCome on, guys!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你们听到那个人的声音了……来吧，伙计们！"},{"uid":"410401801:15:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401801:15:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401801:16:1","speaker":"Alice","text":"I have reservations about this,\nbut very well.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对此我有所保留，但很好。"},{"uid":"410401801:16:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410401801:17:1","speaker":"","text":"","pose":0,"background":"bg_black","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401801:18:1","speaker":"Klein","text":"Whew... It's good to be alive.","pose":10080406,"background":"bg_event_fire_cave_boss","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"呼……活着真好。"}]},{"id":19,"order":19,"actions":[{"uid":"410401801:19:1","speaker":"Alice","text":"That takes care of the\nDivine Object as well.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"神器也可以。"},{"uid":"410401801:19:2","speaker":"Leafa","text":"","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:19:3","speaker":"Asuna","text":"","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":20,"order":20,"actions":[{"uid":"410401801:20:1","speaker":"Klein","text":"Thanks, guys. Things were really\nlooking dicey after she wiped out\nGeneral Eugene and his squad...","pose":100804042,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"谢谢你们。在她消灭了尤金将军和他的小队之后，事情看起来真的很危险……"}]},{"id":21,"order":21,"actions":[{"uid":"410401801:21:1","speaker":"Leafa","text":"So not even they stood a chance?\nWow...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以连他们都没有机会了？哇..."},{"uid":"410401801:21:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:21:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410401801:22:1","speaker":"Alice","text":"Perhaps the men of this land were\ndeceived by the enemy's\nappearance, much as he was?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"或许这片土地上的男人也和他一样，被敌人的外表所欺骗了？"}]},{"id":23,"order":23,"actions":[{"uid":"410401801:23:1","speaker":"Alice","text":"I imagine they were entranced by\nHel's looks and she used it to\nher advantage.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我想他们是被赫尔的外表迷住了，她利用了这一点。"}]},{"id":24,"order":24,"actions":[{"uid":"410401801:24:1","speaker":"Alice","text":"Much like Urdr and Freyja, these\nfalse Divine Object goddesses are\ntruly formidable...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"就像乌尔德和芙蕾雅一样，这些假神器女神真的很强大……"}]},{"id":25,"order":25,"actions":[{"uid":"410401801:25:1","speaker":"Asuna","text":"You can say that again...","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你再说一遍……"},{"uid":"410401801:25:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410401801:26:1","speaker":"Klein","text":"What?! F-Freyja?! Asuna, you\ndidn't tell me Freyja was with\nyou too!","pose":10080408,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"什么？！ F-芙蕾雅？！ 亚丝娜，你没有告诉我芙蕾雅也和你在一起！"}]},{"id":27,"order":27,"actions":[{"uid":"410401801:27:1","speaker":"Asuna","text":"Well, uh, she's not anymore. She\nkind of... went back to just being\na Divine Object...","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，呃，她已经不在了。她有点...回到了神器..."},{"uid":"410401801:27:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401801:27:3","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410401801:28:1","speaker":"Klein","text":"Please, you've gotta fill me in!","pose":10080407,"background":"","item":"","illustration":"","speaker_zh":"克莱因","text_zh":"拜托，你必须填写我的信息！"}]},{"id":29,"order":29,"actions":[{"uid":"410401801:29:1","speaker":"Asuna","text":"Sorry, Klein. I would, but we're\nreally in a hurry now. Some other\ntime, okay!","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"对不起，克莱因。我愿意，但我们现在真的很着急。其他时间，好吧！"},{"uid":"410401801:29:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401801:29:3","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410401801:30:1","speaker":"Alice","text":"Come, Asuna, Leafa, and Urdr.\nLet us be on our way.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"来吧，亚丝娜、莉法、乌尔德。让我们上路吧。"}]},{"id":31,"order":31,"actions":[{"uid":"410401801:31:1","speaker":"Leafa","text":"Okay.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"好的。"}]},{"id":32,"order":32,"actions":[{"uid":"410401801:32:1","speaker":"Alice","text":"Amayori, take us to the\nland of the cat fairies...\nOur final destination!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"雨缘，带我们去猫仙之国……我们的最终目的地！"}]},{"id":33,"order":33,"actions":[{"uid":"410401801:33:1","speaker":"Amayori","text":"Piii!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"啾！"},{"uid":"410401801:33:2","speaker":"リーファ","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410401801:34:1","speaker":"Sinon","text":"Are you okay, Silica?!","pose":100402012,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"西莉卡，你还好吗？！"},{"uid":"410401801:34:2","speaker":"Silica","text":"","pose":100604062,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410401801:35:1","speaker":"Silica","text":"I-I'm sorry, Sinon...\nI think... this is it for me...","pose":100604062,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我、对不起，诗乃...我想...这就是我的了..."}]},{"id":36,"order":36,"actions":[{"uid":"410401801:36:1","speaker":"Sinon","text":"Got it... Go on and head back to\nAlicia's estate. I'll be okay.","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"知道了……继续回亚莉莎的庄园吧。我会没事的。"}]},{"id":37,"order":37,"actions":[{"uid":"410401801:37:1","speaker":"Silica","text":"I can't leave you, Sinon! Not even\nthe dragoons could handle him!","pose":100604082,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我不能离开你，诗乃！连龙骑都对付不了他！"}]},{"id":38,"order":38,"actions":[{"uid":"410401801:38:1","speaker":"Sinon","text":"If we let him run around\nunchecked, Alicia will be the\nnext to die... Please, Silica.","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"如果任由他乱跑的话，下一个死的就是亚莉莎……拜托了，西莉卡。"}]},{"id":39,"order":39,"actions":[{"uid":"410401801:39:1","speaker":"Silica","text":"A-Alright! Sorry about this,\nSinon!","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"好、好的！抱歉，诗乃！"},{"uid":"410401801:39:2","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410401801:40:1","speaker":"Odin","text":"You've done well to survive this\nfar... But this is the end.","pose":20380105,"background":"","item":"","illustration":"","speaker_zh":"奥丁","text_zh":"你能活到现在已经做得很好了……但这就是结局了。"}]},{"id":41,"order":41,"actions":[{"uid":"410401801:41:1","speaker":"Sinon","text":"...","pose":100402072,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"..."}]},{"id":42,"order":42,"actions":[{"uid":"410401801:42:1","speaker":"Odin","text":"Hm. Reinforcements, I see.","pose":20380101,"background":"","item":"","illustration":"","speaker_zh":"奥丁","text_zh":"嗯。增援，我明白了。"}]},{"id":43,"order":43,"actions":[{"uid":"410401801:43:1","speaker":"Kirito","text":"Sinon, we're here!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"诗乃，我们来了！"},{"uid":"410401801:43:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:43:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410401801:44:1","speaker":"Sinon","text":"Kirito! And Eugeo!","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"桐人！还有尤吉欧！"}]},{"id":45,"order":45,"actions":[{"uid":"410401801:45:1","speaker":"Asuna","text":"Don't forget us!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不要忘记我们！"},{"uid":"410401801:45:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:45:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410401801:46:1","speaker":"Sinon","text":"Asuna! Leafa!","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"亚丝娜！ 莉法！"},{"uid":"410401801:46:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:46:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":47,"order":47,"actions":[{"uid":"410401801:47:1","speaker":"Leafa","text":"Sinon! Thank goodness we made\nit in time!","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"诗乃！谢天谢地，我们及时赶到了！"},{"uid":"410401801:47:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:47:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410401801:48:1","speaker":"Eugeo","text":"Good to see you all again too!\nLooks like we all managed to meet\nup just like we promised.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"也很高兴再次见到大家！看起来我们都像我们承诺的那样成功见面了。"},{"uid":"410401801:48:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:48:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410401801:49:1","speaker":"Alice","text":"Eugeo, Kirito, how did things fare\non your end?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧、桐人，你们那边怎么样了？"},{"uid":"410401801:49:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:49:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410401801:50:1","speaker":"Kirito","text":"We managed to beat Tyr and Freyja\nand take back the Divine Objects.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们成功击败了提尔和芙蕾雅，夺回了神器。"},{"uid":"410401801:50:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401801:50:3","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410401801:51:1","speaker":"Alice","text":"Good. We defeated Hel and Loki as\nwell. Their Divine Objects are\nright here.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好。我们还击败了赫尔和洛基。他们的神器就在这里。"},{"uid":"410401801:51:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:51:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":52,"order":52,"actions":[{"uid":"410401801:52:1","speaker":"Kirito","text":"Great. That leaves just Odin, then!\nNow that we're all together, I'm\nsure we can take him! Come on!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了。那么就只剩下奥丁了！现在我们齐心协力，我相信我们可以抓住他！快点！"},{"uid":"410401801:52:2","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:52:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410401801:53:1","speaker":"Asuna","text":"Let's do this!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们开始吧！"},{"uid":"410401801:53:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:53:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410401801:54:1","speaker":"","text":"","pose":0,"background":"bg_black","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410401801:55:1","speaker":"Odin","text":"It's not possible... How could I,\nthe lord of all the gods... prove\nlesser than mere fairies...?!","pose":20380101,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"奥丁","text_zh":"这不可能……我这个众神之主……怎么可能连仙子都不如……！"}]},{"id":56,"order":56,"actions":[{"uid":"410401801:56:1","speaker":"Kirito","text":"Great, that takes care of all the\ngods!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了，照顾众神了！"},{"uid":"410401801:56:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:56:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410401801:57:1","speaker":"Asuna","text":"We did it! And we got the last\nDivine Object too!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们做到了！我们也得到了最后一个神器！"},{"uid":"410401801:57:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:57:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410401801:58:1","speaker":"Alice","text":"Now we have all seven...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"现在我们七个人都有了……"},{"uid":"410401801:58:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410401801:59:1","speaker":"Urdr","text":"Wait, brave warriors.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"等等，勇敢的战士们。"}]},{"id":60,"order":60,"actions":[{"uid":"410401801:60:1","speaker":"Alice","text":"Urdr... What is it?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"乌尔德...是什么？"},{"uid":"410401801:60:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:60:3","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410401801:61:1","speaker":"Urdr","text":"Over there. Odin's form is...\nchanging.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"那边。奥丁的形态正在……改变。"}]},{"id":62,"order":62,"actions":[{"uid":"410401801:62:1","speaker":"???","text":"Rrrghhh...!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"呜呜呜……！"}]},{"id":63,"order":63,"actions":[{"uid":"410401801:63:1","speaker":"???","text":"Graaahhh!!!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"嘎啊啊！！！"}]},{"id":64,"order":64,"actions":[{"uid":"410401801:64:1","speaker":"Eugeo","text":"Wh-What is that? Some kind\nof... wolf monster?!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"什、那是什么？某种……狼怪物？！"},{"uid":"410401801:64:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:64:3","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410401801:65:1","speaker":"???","text":"Grrrrrr!","pose":20430101,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"？？？","text_zh":"咕咕咕！"}]},{"id":66,"order":66,"actions":[{"uid":"410401801:66:1","speaker":"Kirito","text":"What... is that?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那是什么……？！"},{"uid":"410401801:66:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:66:3","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":67,"order":67,"actions":[{"uid":"410401801:67:1","speaker":"Leafa","text":"No way... Fenrir?!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"不可能吧……芬里尔？！"}]},{"id":68,"order":68,"actions":[{"uid":"410401801:68:1","speaker":"Sinon","text":"The enormous wolf in Norse\nmythology that ate Odin himself...","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"北欧神话中吃掉奥丁本人的巨狼……"}]},{"id":69,"order":69,"actions":[{"uid":"410401801:69:1","speaker":"Asuna","text":"Uh oh. Everyone, look at that\nmonster's stats!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃哦。大家看看那个怪物的数据吧！"},{"uid":"410401801:69:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401801:69:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410401801:70:1","speaker":"Kirito","text":"...Huh?! What's going on?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……啊？！这是怎么回事？！"},{"uid":"410401801:70:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:70:3","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401801:71:1","speaker":"Kirito","text":"How can its stats be tens of times\ngreater than Odin and the other\ngods?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"属性怎么可能比奥丁等神强几十倍？"}]},{"id":72,"order":72,"actions":[{"uid":"410401801:72:1","speaker":"Eugeo","text":"What does that mean?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"什么意思？"},{"uid":"410401801:72:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:72:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410401801:73:1","speaker":"Alice","text":"So this creature is now tens of\ntimes stronger than our previous\ngodly opponents?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这么说这个生物现在比我们之前的神级对手强了几十倍？"}]},{"id":74,"order":74,"actions":[{"uid":"410401801:74:1","speaker":"Asuna","text":"L-Looks that way...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"L、看起来是这样……"}]},{"id":75,"order":75,"actions":[{"uid":"410401801:75:1","speaker":"Leafa","text":"Maybe it's because it has the\nstrength of the gods inside, like\nin the myth where it eats Odin?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"或许是因为它体内有神的力量，就像神话里吃掉奥丁一样？"},{"uid":"410401801:75:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:75:3","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410401801:76:1","speaker":"Urdr","text":"Brave warriors...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"勇敢的战士..."}]},{"id":77,"order":77,"actions":[{"uid":"410401801:77:1","speaker":"Urdr","text":"This is the will of this world...\nThe Divine Objects were but a\nmeans to save this land.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这就是这个世界的意志……神器只是拯救这片土地的手段。"}]},{"id":78,"order":78,"actions":[{"uid":"410401801:78:1","speaker":"Urdr","text":"Though they may be in your\nhands now, that does not alter\nthe world's intentions.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"虽然现在它们可能在你手中，但这并不能改变世界的意图。"}]},{"id":79,"order":79,"actions":[{"uid":"410401801:79:1","speaker":"Urdr","text":"It will continue to change its\ntactics and create new foes until\nthe foreign elements are gone...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"它会不断改变战术，制造新的敌人，直到外来因素消失……"}]},{"id":80,"order":80,"actions":[{"uid":"410401801:80:1","speaker":"Alice","text":"Urdr! You would betray us again?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"乌尔德！你又要背叛我们？！"},{"uid":"410401801:80:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401801:80:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":81,"order":81,"actions":[{"uid":"410401801:81:1","speaker":"Kirito","text":"That's not it, Alice... I think\nshe's just speaking for the world\nright now. She's not our enemy.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不是这样的，爱丽丝……我觉得她现在只是在为世界说话。她不是我们的敌人。"},{"uid":"410401801:81:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:81:3","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410401801:82:1","speaker":"Asuna","text":"So then, the memory defrag is just\ngoing to keep making stronger and\nstronger enemies...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那么，内存碎片整理只会不断制造出越来越强大的敌人……"},{"uid":"410401801:82:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401801:82:3","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410401801:83:1","speaker":"Asuna","text":"Until it finally gets what it\nwants...?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"直到它最终如愿以偿……？"}]},{"id":84,"order":84,"actions":[{"uid":"410401801:84:1","speaker":"Leafa","text":"While using Norse mythology as an\nexcuse for its monster designs,\nlike how Odin turned into Fenrir?","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"怪物设计却以北欧神话为借口，比如奥丁是如何变成芬里尔的？"},{"uid":"410401801:84:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:84:3","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410401801:85:1","speaker":"Kirito","text":"I think you're right...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我觉得你是对的……"},{"uid":"410401801:85:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401801:86:1","speaker":"Fenrir","text":"Grrraaahhh!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"吼啊啊！"}]},{"id":87,"order":87,"actions":[{"uid":"410401801:87:1","speaker":"Asuna","text":"It's coming!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"来了！"},{"uid":"410401801:87:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401801:87:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410401801:88:1","speaker":"Kirito","text":"I guess we have no choice but to\nfight...!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来我们只能战斗了……！"},{"uid":"410401801:88:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:88:3","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410401801:89:1","speaker":"Fenrir","text":"Graaahhh!","pose":20430101,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"格拉啊啊啊！"}]},{"id":90,"order":90,"actions":[{"uid":"410401801:90:1","speaker":"Leafa","text":"Aaah!","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"啊啊！"},{"uid":"410401801:90:2","speaker":"Sinon","text":"","pose":100402012,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:90:3","speaker":"Asuna","text":"","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401801:91:1","speaker":"Sinon","text":"Leafa!","pose":100402012,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"莉法！"}]},{"id":92,"order":92,"actions":[{"uid":"410401801:92:1","speaker":"Asuna","text":"There's no way we can possibly\ndefeat it now! We need to get\nout of here and regrou...","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"现在根本不可能打败它！我们需要离开这里并重新集结..."},{"uid":"410401801:92:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410401801:93:1","speaker":"Fenrir","text":"Graaah!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"啊啊啊！"}]},{"id":94,"order":94,"actions":[{"uid":"410401801:94:1","speaker":"Asuna","text":"Aah!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊啊！"},{"uid":"410401801:94:2","speaker":"Leafa","text":"","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:94:3","speaker":"Sinon","text":"","pose":100402012,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":95,"order":95,"actions":[{"uid":"410401801:95:1","speaker":"Kirito","text":"Looks like it's not even going to\nlet us escape...!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来连我们都逃不掉了……！"},{"uid":"410401801:95:2","speaker":"Eugeo","text":"","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401801:95:3","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410401801:96:1","speaker":"Eugeo","text":"Kirito, you and the others should\nfall back and heal! Alice and I\nwill draw its attention!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人，你和其他人应该退后疗伤！ 爱丽丝我会引起它的注意！"}]},{"id":97,"order":97,"actions":[{"uid":"410401801:97:1","speaker":"Kirito","text":"Eugeo?!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧？！"}]},{"id":98,"order":98,"actions":[{"uid":"410401801:98:1","speaker":"Alice","text":"Don't worry! We wield the power of\nthe Divine Objects! We should be\nable to hold out for a while!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"别担心！我们运用神器的力量！我们应该还能坚持一段时间！"}]},{"id":99,"order":99,"actions":[{"uid":"410401801:99:1","speaker":"Kirito","text":"Right... Hang in there!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对了……坚持住！"},{"uid":"410401801:99:2","speaker":"Eugeo","text":"","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401801:100:1","speaker":"Leafa","text":"Man, this is tough...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"伙计，这太难了……"},{"uid":"410401801:100:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410401801:101:1","speaker":"Sinon","text":"I know... That thing's way out of\nour league, and we can't even run\naway...","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我知道……那东西根本不是我们的能力，我们根本就跑不了……"}]},{"id":102,"order":102,"actions":[{"uid":"410401801:102:1","speaker":"Kirito","text":"Yeah... It's a good thing Alice\nand Eugeo were around.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……幸好有爱丽丝和尤吉欧在。"},{"uid":"410401801:102:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401801:103:1","speaker":"Urdr","text":"Since we let you escape in our\nfirst battle, I imagine Fenrir\nmeans to not repeat that mistake.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"既然我们在第一场战斗中就让你逃脱了，我想芬里尔就不会再犯同样的错误了。"}]},{"id":104,"order":104,"actions":[{"uid":"410401801:104:1","speaker":"Kirito","text":"So the enemy's always one step\nahead of us, constantly plotting\nout its next move...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原来敌人总是先我们一步，不断地谋划着下一步行动……"},{"uid":"410401801:104:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401801:105:1","speaker":"Asuna","text":"That's a Cardinal quest for you...\nThis is like trying to outsmart\nthe world itself.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这对你来说是一个卡迪纳尔的任务……这就像试图超越世界本身。"}]},{"id":106,"order":106,"actions":[{"uid":"410401801:106:1","speaker":"Sinon","text":"Kirito, Asuna... What's going on\nhere, anyway?","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"桐人、亚丝娜……这到底是怎么回事？"},{"uid":"410401801:106:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410401801:107:1","speaker":"Kirito","text":"It turns out that ALO sees Alice\nand Eugeo as foreign elements.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原来ALO将爱丽丝和尤吉欧视为外来元素。"},{"uid":"410401801:107:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410401801:108:1","speaker":"Kirito","text":"So it made the Divine Objects,\nwhich can do almost anything,\nto try and get rid of them...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以它制造了几乎无所不能的神器，试图摆脱它们……"}]},{"id":109,"order":109,"actions":[{"uid":"410401801:109:1","speaker":"Asuna","text":"The Objects used super OP enemies\nand quests to erase them from this\nworld, but it hasn't worked.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"物体使用超级OP敌人和任务将它们从这个世界上抹去，但并没有奏效。"}]},{"id":110,"order":110,"actions":[{"uid":"410401801:110:1","speaker":"Asuna","text":"And after repeating that process a\nfew times, it led to this actual\nmonster we're facing now...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"重复这个过程几次后，就导致了我们现在面对的这个真正的怪物……"}]},{"id":111,"order":111,"actions":[{"uid":"410401801:111:1","speaker":"Kirito","text":"Cardinal's greatest strength\nis its adaptability. Stronger\nenemies, Hi-Mobs...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"卡迪纳尔最大的优点就是适应性。更强大的敌人，Hi-Mobs..."}]},{"id":112,"order":112,"actions":[{"uid":"410401801:112:1","speaker":"Kirito","text":"And now, making gods straight\nout of Norse mythology.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"现在，直接从北欧神话中创造神。"}]},{"id":113,"order":113,"actions":[{"uid":"410401801:113:1","speaker":"Kirito","text":"Now it's just continuing to make\nnew enemies out of nothing, even\nwithout the Divine Objects...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"现在就是继续无中生有地制造新的敌人，连神器都没有了……"}]},{"id":114,"order":114,"actions":[{"uid":"410401801:114:1","speaker":"Asuna","text":"It's executing a memory defrag, to\nput all the pieces of its records\nand systems back in order.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"它正在执行内存碎片整理，将其所有记录和系统碎片恢复正常。"}]},{"id":115,"order":115,"actions":[{"uid":"410401801:115:1","speaker":"Leafa","text":"So what do we do about it? At this\nrate, I don't see how we can stop\nthis for good.","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"那我们该怎么办呢？按照这个速度，我不知道我们如何才能永远阻止这种情况。"},{"uid":"410401801:115:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401801:116:1","speaker":"Kirito","text":"Well... There is one way to stop\nthis fight...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……有一个方法可以阻止这场战斗……"},{"uid":"410401801:116:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":117,"order":117,"actions":[{"uid":"410401801:117:1","speaker":"Sinon","text":"What is it?","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"什么？"},{"uid":"410401801:117:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410401801:118:1","speaker":"Kirito","text":"Urdr, remember how you absorbed a\nDivine Object's power before?\nCould we do that too?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"乌尔德，还记得你之前是怎么吸收神器力量的吗？我们也可以这样做吗？"},{"uid":"410401801:118:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410401801:119:1","speaker":"Urdr","text":"...It is possible. Though only if\nyou are capable of controlling\nsuch enormous power.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"……有可能。但前提是你有能力掌控如此巨大的力量。"}]},{"id":120,"order":120,"actions":[{"uid":"410401801:120:1","speaker":"Kirito","text":"Great, do it. We have seven Divine\nObjects here. We're going to take\ntheir power and use it ourselves.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了，就这么做吧。我们这里有七件神物。我们将夺取他们的权力并为我们自己使用。"},{"uid":"410401801:120:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401801:121:1","speaker":"Asuna","text":"Now I see... We can use them\nto power ourselves up,\nlike Alice and Eugeo.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"现在我明白了……我们可以用它们来给自己加电，比如爱丽丝和尤吉欧。"}]},{"id":122,"order":122,"actions":[{"uid":"410401801:122:1","speaker":"Leafa","text":"But they're in the middle of a\nbattle. How are we going to get\nthe Divine Objects to them?","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"但是他们正处于战斗之中。我们如何将神器交给他们？"},{"uid":"410401801:122:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410401801:123:1","speaker":"Yuuki","text":"If that's the case, I'll take one\ntoo!","pose":10050107,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"既然如此，我也来一份吧！"},{"uid":"410401801:123:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410401801:124:1","speaker":"Asuna","text":"Yuuki! You came!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"优纪！你来了！"},{"uid":"410401801:124:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410401801:125:1","speaker":"Yuuki","text":"You bet! Sorry I took so long!\nYou don't mind if I use one of\nthose things, do you, Kirito?","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"你赌！抱歉我花了这么长时间！你不介意我使用其中之一吧，桐人？"},{"uid":"410401801:125:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:125:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410401801:126:1","speaker":"Kirito","text":"Not at all. Besides...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"完全没有。除此之外..."},{"uid":"410401801:126:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410401801:127:1","speaker":"Kirito","text":"We should use these Objects up\ncompletely, so we don't have to\ndeal with any more gods.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们应该把这些东西全部用完，这样我们就不用再跟神打交道了。"}]},{"id":128,"order":128,"actions":[{"uid":"410401801:128:1","speaker":"Asuna","text":"But, Kirito, didn't you say before\nthat no player can destroy\nthe Objects?","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是，桐人，你之前不是说过玩家不能破坏Object吗？"}]},{"id":129,"order":129,"actions":[{"uid":"410401801:129:1","speaker":"Kirito","text":"That's true, but when you get down\nto it, they're nothing more than\nreally dense energy clusters.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"确实如此，但仔细想想，它们只不过是非常密集的能量团而已。"}]},{"id":130,"order":130,"actions":[{"uid":"410401801:130:1","speaker":"Kirito","text":"So even if we can't physically\nbreak them, we can still make\nsure to use up all their energy!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以即使我们无法从物理上破坏它们，我们仍然可以确保耗尽它们的能量！"}]},{"id":131,"order":131,"actions":[{"uid":"410401801:131:1","speaker":"Kirito","text":"Especially now that we know\nthey're not good for anything\nbut causing trouble.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤其是现在我们知道他们除了制造麻烦之外没有任何好处。"}]},{"id":132,"order":132,"actions":[{"uid":"410401801:132:1","speaker":"Sinon","text":"Okay. Let's do it!","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"好的。我们开始做吧！"},{"uid":"410401801:132:2","speaker":"Yuuki","text":"","pose":10050107,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""},{"uid":"410401801:132:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410401801:133:1","speaker":"Leafa","text":"Yeah!","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"嗯！"},{"uid":"410401801:133:2","speaker":"シノン","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:133:3","speaker":"ユウキ","text":"","pose":10050107,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410401801:134:1","speaker":"Fenrir","text":"Graaahhh!","pose":20430101,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"格拉啊啊啊！"}]},{"id":135,"order":135,"actions":[{"uid":"410401801:135:1","speaker":"Eugeo","text":"Kgh, looks like this is as far as\nI can go!","pose":105302062,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哎呀，看来我只能走到这里了！"},{"uid":"410401801:135:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":136,"order":136,"actions":[{"uid":"410401801:136:1","speaker":"Alice","text":"Eugeo!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧！"}]},{"id":137,"order":137,"actions":[{"uid":"410401801:137:1","speaker":"Eugeo","text":"Alice, get back!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝，回来吧！"}]},{"id":138,"order":138,"actions":[{"uid":"410401801:138:1","speaker":"Alice","text":"Don't be ridiculous! I'm an\nIntegrity Knight! I won't be\nintimidated by a mere beast!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"别开玩笑了！我是整合骑士！我不会被区区的野兽吓倒！"},{"uid":"410401801:138:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401801:139:1","speaker":"Fenrir","text":"Grrr!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"呜呜！"}]},{"id":140,"order":140,"actions":[{"uid":"410401801:140:1","speaker":"Eugeo","text":"Argh!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"啊啊！"},{"uid":"410401801:140:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":141,"order":141,"actions":[{"uid":"410401801:141:1","speaker":"Alice","text":"Eugeo!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧！"}]},{"id":142,"order":142,"actions":[{"uid":"410401801:142:1","speaker":"Kirito","text":"Raaah!","pose":10013201,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇啊！"}]},{"id":143,"order":143,"actions":[{"uid":"410401801:143:1","speaker":"","text":"","pose":0,"background":"bg_black","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":144,"order":144,"actions":[{"uid":"410401801:144:1","speaker":"Yuuki","text":"Haaa!","pose":10051301,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"优纪","text_zh":"哈哈！"}]},{"id":145,"order":145,"actions":[{"uid":"410401801:145:1","speaker":"","text":"","pose":0,"background":"bg_black","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":146,"order":146,"actions":[{"uid":"410401801:146:1","speaker":"Alice","text":"Kirito?! Yuuki?!\nWhat happened to you?!","pose":10540108,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人？！ 优纪？！你怎么了？！"},{"uid":"410401801:146:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":147,"order":147,"actions":[{"uid":"410401801:147:1","speaker":"Leafa","text":"Alice, take care of Eugeo!\nAsuna, you know what to do!","pose":10032707,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"爱丽丝，照顾好尤吉欧！ 亚丝娜，你知道该怎么做！"},{"uid":"410401801:147:2","speaker":"Asuna","text":"","pose":10023807,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401801:147:3","speaker":"Sinon","text":"","pose":10043001,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410401801:148:1","speaker":"Asuna","text":"Yep, I've got this!","pose":10023807,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，我有这个！"}]},{"id":149,"order":149,"actions":[{"uid":"410401801:149:1","speaker":"Sinon","text":"I'm just getting started... Yah!","pose":10043001,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我才刚刚开始……啊！"},{"uid":"410401801:149:2","speaker":"Leafa","text":"","pose":10032707,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:149:3","speaker":"Asuna","text":"","pose":10023807,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410401801:150:1","speaker":"Fenrir","text":"Grrkrk!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"天哪！"}]},{"id":151,"order":151,"actions":[{"uid":"410401801:151:1","speaker":"Alice","text":"Did you... Did you all use the\nDivine Objects yourselves?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你们……你们都是自己使用神器的吗？"},{"uid":"410401801:151:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":152,"order":152,"actions":[{"uid":"410401801:152:1","speaker":"Kirito","text":"That's right.","pose":10013207,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊。"},{"uid":"410401801:152:2","speaker":"Yuuki","text":"","pose":10051307,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410401801:153:1","speaker":"Urdr","text":"Foreign element...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"外来元素……"}]},{"id":154,"order":154,"actions":[{"uid":"410401801:154:1","speaker":"Alice","text":"Urdr?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"乌尔德？"},{"uid":"410401801:154:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":155,"order":155,"actions":[{"uid":"410401801:155:1","speaker":"Urdr","text":"Here. The last Divine Object's\npower is yours...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这里。最后的神器的力量是你的......"}]},{"id":156,"order":156,"actions":[{"uid":"410401801:156:1","speaker":"Alice","text":"But this is...!","pose":10540508,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是这是……！"},{"uid":"410401801:156:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":157,"order":157,"actions":[{"uid":"410401801:157:1","speaker":"Alice","text":"This is the power of the goddess\nherself? With this... I am certain\nwe can defeat that creature!","pose":10540508,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这就是女神本身的力量？有了这个……我确信我们能够打败那个生物！"}]},{"id":158,"order":158,"actions":[{"uid":"410401801:158:1","speaker":"Kirito","text":"Great, it looks like you've\nabsorbed the Divine Object too.","pose":10013207,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了，看来你也吸收了神器。"},{"uid":"410401801:158:2","speaker":"Yuuki","text":"","pose":10051307,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":159,"order":159,"actions":[{"uid":"410401801:159:1","speaker":"Asuna","text":"Now we can use all seven!","pose":10023807,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"现在七个都可以用了！"},{"uid":"410401801:159:2","speaker":"Sinon","text":"","pose":10043001,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:159:3","speaker":"Leafa","text":"","pose":10032707,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":160,"order":160,"actions":[{"uid":"410401801:160:1","speaker":"Kirito","text":"Everyone! Blow up your strength as\nhigh as it can go! We're going to\nuse the Objects up completely!","pose":10013201,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"大家好！尽可能地增强你的力量！我们将完全使用这些对象！"},{"uid":"410401801:160:2","speaker":"Yuuki","text":"","pose":10051307,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":161,"order":161,"actions":[{"uid":"410401801:161:1","speaker":"","text":"Yeah!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"","text_zh":"嗯！"},{"uid":"410401801:161:2","speaker":"キリト","text":"","pose":10013201,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:161:3","speaker":"ユウキ","text":"","pose":10051307,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":162,"order":162,"actions":[{"uid":"410401801:162:1","speaker":"Fenrir","text":"Graaahhh!","pose":20430101,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"格拉啊啊啊！"}]},{"id":163,"order":163,"actions":[{"uid":"410401801:163:1","speaker":"","text":"","pose":0,"background":"bg_black","item":"","illustration":"","speaker_zh":"","text_zh":""}]},{"id":164,"order":164,"actions":[{"uid":"410401801:164:1","speaker":"Kirito","text":"Alright, we beat Fenrir!","pose":10011505,"background":"bg_event_peaceful_town","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好了，我们打败了芬里尔！"},{"uid":"410401801:164:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:164:3","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":165,"order":165,"actions":[{"uid":"410401801:165:1","speaker":"Leafa","text":"Hey, Kirito, you're back to\nnormal.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"嘿，桐人，你恢复正常了。"}]},{"id":166,"order":166,"actions":[{"uid":"410401801:166:1","speaker":"Sinon","text":"Looks like we all managed to use\nup the Objects' power, just like\nwe planned.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"看来我们都用完了物体的力量，就像我们计划的那样。"}]},{"id":167,"order":167,"actions":[{"uid":"410401801:167:1","speaker":"Asuna","text":"O-Oh no...!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"噢、噢不……！"},{"uid":"410401801:167:2","speaker":"Yuuki","text":"","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":168,"order":168,"actions":[{"uid":"410401801:168:1","speaker":"Yuuki","text":"What is it, Asuna?\nOh no, Eugeo!","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"什么啊，亚丝娜？哦不，尤吉欧！"}]},{"id":169,"order":169,"actions":[{"uid":"410401801:169:1","speaker":"Eugeo","text":"Nngh...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯……"},{"uid":"410401801:169:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":170,"order":170,"actions":[{"uid":"410401801:170:1","speaker":"Alice","text":"Eugeo suffered a terrible injury\nin order to protect me... He'll\ndie unless something is done.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧为了保护我受了重伤……不采取措施他就会死。"}]},{"id":171,"order":171,"actions":[{"uid":"410401801:171:1","speaker":"Kirito","text":"No...!","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不……！"},{"uid":"410401801:171:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:171:3","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":172,"order":172,"actions":[{"uid":"410401801:172:1","speaker":"Asuna","text":"I'm so sorry. My healing magic\nisn't doing a thing...","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"非常抱歉。我的治愈魔法没有任何作用……"},{"uid":"410401801:172:2","speaker":"Yuuki","text":"","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":173,"order":173,"actions":[{"uid":"410401801:173:1","speaker":"Kirito","text":"If even Asuna's maxed-out healing\ndoesn't work, I don't know what we\ncan do...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果连亚丝娜的治愈满级都不起作用的话，我真不知道该怎么办了……"},{"uid":"410401801:173:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:173:3","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":174,"order":174,"actions":[{"uid":"410401801:174:1","speaker":"Urdr","text":"Look, brave warriors. Over there.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"看，勇敢的战士们。在那边。"}]},{"id":175,"order":175,"actions":[{"uid":"410401801:175:1","speaker":"Kirito","text":"Isn't that just the place where\nFenrir disappeared?\n...Wait. Is that a Divine Object?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那不就是芬里尔消失的地方吗？ ...等待。那是神器吗？！"},{"uid":"410401801:175:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401801:175:3","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":176,"order":176,"actions":[{"uid":"410401801:176:1","speaker":"Asuna","text":"There's an eighth one?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"还有第八个？！"},{"uid":"410401801:176:2","speaker":"Yuuki","text":"","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":177,"order":177,"actions":[{"uid":"410401801:177:1","speaker":"Sinon","text":"I'm not sure... I think it might\njust be the original resources\nthat were used to make Fenrir.","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我不确定……我想这可能只是用来制作芬里尔的原始资源。"},{"uid":"410401801:177:2","speaker":"Kirito","text":"","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:177:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":178,"order":178,"actions":[{"uid":"410401801:178:1","speaker":"Kirito","text":"Maybe we can use it to save\nEugeo's life!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许我们可以用它来拯救尤吉欧的生命！"}]},{"id":179,"order":179,"actions":[{"uid":"410401801:179:1","speaker":"Kirito","text":"Eugeo, absorb that Divine Object\ninto your body, just like we did!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧，把那个神器吸收到你的身体里，就像我们一样！"},{"uid":"410401801:179:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":180,"order":180,"actions":[{"uid":"410401801:180:1","speaker":"Eugeo","text":"Kiri... to...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"Kiri...到..."},{"uid":"410401801:180:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":181,"order":181,"actions":[{"uid":"410401801:181:1","speaker":"Eugeo","text":"It's okay...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"没关系……"}]},{"id":182,"order":182,"actions":[{"uid":"410401801:182:1","speaker":"Kirito","text":"Wh-What are you saying?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什、你说什么？！"},{"uid":"410401801:182:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:182:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":183,"order":183,"actions":[{"uid":"410401801:183:1","speaker":"Eugeo","text":"We knew that our being here\nwas why this world had become\nso chaotic...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们知道，正是因为我们的存在，这个世界才变得如此混乱……"},{"uid":"410401801:183:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":184,"order":184,"actions":[{"uid":"410401801:184:1","speaker":"Asuna","text":"...!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"...!"},{"uid":"410401801:184:2","speaker":"Yuuki","text":"","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":185,"order":185,"actions":[{"uid":"410401801:185:1","speaker":"Eugeo","text":"And now time's up... We never\nfound a way back, and the world\nis on the brink of collapse...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"现在时间到了……我们再也找不到回去的路了，世界正处于崩溃的边缘……"},{"uid":"410401801:185:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":186,"order":186,"actions":[{"uid":"410401801:186:1","speaker":"Kirito","text":"Eugeo!","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧！"},{"uid":"410401801:186:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:186:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":187,"order":187,"actions":[{"uid":"410401801:187:1","speaker":"???","text":"Grrr!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"呜呜！"}]},{"id":188,"order":188,"actions":[{"uid":"410401801:188:1","speaker":"Sinon","text":"What?!","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"什么？！"},{"uid":"410401801:188:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:188:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":189,"order":189,"actions":[{"uid":"410401801:189:1","speaker":"Leafa","text":"H-How can this be happening?","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"这、怎么会这样？"},{"uid":"410401801:189:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":190,"order":190,"actions":[{"uid":"410401801:190:1","speaker":"Yuuki","text":"It's not just one Fenrir...\nIt's a whole bunch of them...","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"不只是芬里尔一个……是一大群……"},{"uid":"410401801:190:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":191,"order":191,"actions":[{"uid":"410401801:191:1","speaker":"Fenrir","text":"Grrraaaaaahhh!!!","pose":20430101,"background":"","item":"","illustration":"","speaker_zh":"芬里尔","text_zh":"吼啊啊！"},{"uid":"410401801:191:2","speaker":"Yuuki","text":"","pose":10050108,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""},{"uid":"410401801:191:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":192,"order":192,"actions":[{"uid":"410401801:192:1","speaker":"Urdr","text":"It seems this world has prepared\nyet more assassins.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"看来这个世界又准备了更多的刺客。"}]},{"id":193,"order":193,"actions":[{"uid":"410401801:193:1","speaker":"Asuna","text":"No way... We barely beat one of\nthem. Now that the Objects' power\nis gone, we don't stand a chance...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不可能……我们勉强击败了其中一个。既然物体的力量消失了，我们就没有机会了……"},{"uid":"410401801:193:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":194,"order":194,"actions":[{"uid":"410401801:194:1","speaker":"Eugeo","text":"See? We're out of time...\nNow, hurry and... Nngh...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"看到了吗？我们没时间了……现在，快点……嗯……"},{"uid":"410401801:194:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":195,"order":195,"actions":[{"uid":"410401801:195:1","speaker":"Alice","text":"Allow me. Kirito... Asuna...\nAll of you...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"让我来。 桐人... 亚丝娜... 你们所有人..."}]},{"id":196,"order":196,"actions":[{"uid":"410401801:196:1","speaker":"Alice","text":"We are grateful for everything\nyou've done for us. However, we\nare proud Integrity Knights...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们感谢您为我们所做的一切。然而，我们很自豪整合骑士团..."}]},{"id":197,"order":197,"actions":[{"uid":"410401801:197:1","speaker":"Alice","text":"We refuse to be a burden to you\nand the other residents of this\nworld any longer.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们拒绝再成为你和这个世界其他居民的负担。"}]},{"id":198,"order":198,"actions":[{"uid":"410401801:198:1","speaker":"Alice","text":"So we would like you to kill us\nboth, right here and now.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所以我们希望你杀了我们两个，就在此时此地。"}]},{"id":199,"order":199,"actions":[{"uid":"410401801:199:1","speaker":"Asuna","text":"Alice... What are you saying?","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝...你说什么？"},{"uid":"410401801:199:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":200,"order":200,"actions":[{"uid":"410401801:200:1","speaker":"Alice","text":"Without a way for us to return,\nthere is but one thing we can do.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们没有办法回去，我们能做的只有一件事。"},{"uid":"410401801:200:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":201,"order":201,"actions":[{"uid":"410401801:201:1","speaker":"Alice","text":"Our presence here is leading to\nthis world's destruction. Once we\nare gone, it should be averted.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们的存在正在导致这个世界的毁灭。一旦我们走了，就应该避免这种情况。"}]},{"id":202,"order":202,"actions":[{"uid":"410401801:202:1","speaker":"Kirito","text":"Wait! It's too soon to just\ngive up!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"等等！现在放弃还为时过早！"},{"uid":"410401801:202:2","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:202:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":203,"order":203,"actions":[{"uid":"410401801:203:1","speaker":"Alice","text":"You will soon forget us anyway...\nIn which case, there should be no\nproblem.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"反正你很快就会忘记我们的……这样的话应该就没有问题了。"},{"uid":"410401801:203:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":204,"order":204,"actions":[{"uid":"410401801:204:1","speaker":"Kirito","text":"...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...!"},{"uid":"410401801:204:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:204:3","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":205,"order":205,"actions":[{"uid":"410401801:205:1","speaker":"Alice","text":"I am sure you too have noticed how\nour memories have become hazy as\nof late...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我相信你也发现我们的记忆最近变得模糊了……"},{"uid":"410401801:205:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":206,"order":206,"actions":[{"uid":"410401801:206:1","speaker":"Alice","text":"It is only a matter of time before\nthe same happens to all of you.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"同样的事情发生在你们身上只是时间问题。"}]},{"id":207,"order":207,"actions":[{"uid":"410401801:207:1","speaker":"Alice","text":"If you're going to forget us no\nmatter what, there should be\nno reason to hesitate.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果你无论如何都要忘记我们，那就没有理由犹豫。"}]},{"id":208,"order":208,"actions":[{"uid":"410401801:208:1","speaker":"Asuna","text":"I-I...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我、我……"},{"uid":"410401801:208:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":209,"order":209,"actions":[{"uid":"410401801:209:1","speaker":"Eugeo","text":"There you have it...\nNow, please. Hurry and kill us...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"给你了...现在，请。快点杀了我们吧……"},{"uid":"410401801:209:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":210,"order":210,"actions":[{"uid":"410401801:210:1","speaker":"Asuna","text":"We can't do that! And we're NOT\ngoing to forget you!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们不能这么做！我们不会忘记你！"},{"uid":"410401801:210:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":211,"order":211,"actions":[{"uid":"410401801:211:1","speaker":"Kirito","text":"...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401801:211:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:211:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":212,"order":212,"actions":[{"uid":"410401801:212:1","speaker":"Kirito","text":"You two are both terrible liars.\nYes, we noticed that you were\nlosing your memories.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你们两个都是大骗子。是的，我们注意到你正在失去记忆。"}]},{"id":213,"order":213,"actions":[{"uid":"410401801:213:1","speaker":"Kirito","text":"Or rather, that you were\nPRETENDING to lose them.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"或者更确切地说，你假装失去了他们。"},{"uid":"410401801:213:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":214,"order":214,"actions":[{"uid":"410401801:214:1","speaker":"Alice","text":"...!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"...!"},{"uid":"410401801:214:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":215,"order":215,"actions":[{"uid":"410401801:215:1","speaker":"Eugeo","text":"...!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"...!"}]},{"id":216,"order":216,"actions":[{"uid":"410401801:216:1","speaker":"Asuna","text":"Kirito...?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人……？"},{"uid":"410401801:216:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":217,"order":217,"actions":[{"uid":"410401801:217:1","speaker":"Kirito","text":"It was all just an act so we\nwouldn't feel bad about killing\nyou two, right?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这只是一场表演，所以我们不会因为杀了你们两个而感到难过，对吧？"},{"uid":"410401801:217:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:217:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":218,"order":218,"actions":[{"uid":"410401801:218:1","speaker":"Kirito","text":"Ha ha, I've really got to hand it\nto you two.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，真的要交给你们两个了。"},{"uid":"410401801:218:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":219,"order":219,"actions":[{"uid":"410401801:219:1","speaker":"Eugeo","text":"Kirito...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人..."},{"uid":"410401801:219:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":220,"order":220,"actions":[{"uid":"410401801:220:1","speaker":"Kirito","text":"Eugeo... On the way here, you\nmixed up Sinon's name with\nSilica's. I'm guessing you were...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧...来的路上，你把诗乃的名字和西莉卡的名字搞混了。我猜你是..."},{"uid":"410401801:220:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:220:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":221,"order":221,"actions":[{"uid":"410401801:221:1","speaker":"Kirito","text":"...trying to show how bad your\nmemory had become,","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……试图表现出你的记忆力变得多么糟糕，"}]},{"id":222,"order":222,"actions":[{"uid":"410401801:222:1","speaker":"Kirito","text":"but I'm afraid it had\nthe opposite effect.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但恐怕效果适得其反。"}]},{"id":223,"order":223,"actions":[{"uid":"410401801:223:1","speaker":"Kirito","text":"We couldn't have mentioned Silica\nmore than a few times, but you\nremembered her name perfectly.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们不可能多次提到西莉卡，但你却把她的名字记住了。"},{"uid":"410401801:223:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":224,"order":224,"actions":[{"uid":"410401801:224:1","speaker":"Eugeo","text":"Ha ha... I guess I didn't think it\nthrough enough.","pose":105302042,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哈哈……看来我想得还不够。"},{"uid":"410401801:224:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":225,"order":225,"actions":[{"uid":"410401801:225:1","speaker":"Alice","text":"Eugeo!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧！"}]},{"id":226,"order":226,"actions":[{"uid":"410401801:226:1","speaker":"Eugeo","text":"Sorry, Alice... Looks like I'm\ndone for anyway, whether\nthey kill me or not...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"对不起，爱丽丝……看来我已经完了，不管他们杀不杀我……"}]},{"id":227,"order":227,"actions":[{"uid":"410401801:227:1","speaker":"Eugeo","text":"I'm sorry I can't do the same\nfor you...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"很抱歉我不能为你做同样的事情......"}]},{"id":228,"order":228,"actions":[{"uid":"410401801:228:1","speaker":"Alice","text":"...No matter. I shall end my own\nlife, with the honor and dignity\nbefitting an Integrity Knight.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……无所谓。我将以整合骑士应有的荣誉和尊严结束自己的生命。"}]},{"id":229,"order":229,"actions":[{"uid":"410401801:229:1","speaker":"Kirito","text":"Wait, wait! Don't give up yet!\nThere HAS to be another way!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"等等，等等！不要放弃！必须有另一种方法！"},{"uid":"410401801:229:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:229:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":230,"order":230,"actions":[{"uid":"410401801:230:1","speaker":"Alice","text":"Then let us battle to the death.\nI shall come at you as if to kill\nyou. You shall do the same.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那我们就决一死战吧。我会冲向你，就像要杀死你一样。你也应该这样做。"},{"uid":"410401801:230:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":231,"order":231,"actions":[{"uid":"410401801:231:1","speaker":"Kirito","text":"What? No, I'm not going to do\nthat! I'm not giving up!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？不，我不会那样做！我不会放弃！"},{"uid":"410401801:231:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:231:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":232,"order":232,"actions":[{"uid":"410401801:232:1","speaker":"Alice","text":"Please, Kirito. We can't bear to\nsee you all so sad... to see this\nworld fall apart because of us!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"请桐人。我们不忍心看到你们如此悲伤……看到这个世界因为我们而分崩离析！"},{"uid":"410401801:232:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":233,"order":233,"actions":[{"uid":"410401801:233:1","speaker":"Alice","text":"You must understand! This is\nthe only solution left to us! We\nsimply don't have any more time!","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你一定要明白！这是留给我们唯一的解决办法了！我们根本没有更多的时间了！"}]},{"id":234,"order":234,"actions":[{"uid":"410401801:234:1","speaker":"Asuna","text":"No... It's too awful!\nThings can't end like this...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不行……太可怕了！事情不能就这样结束..."},{"uid":"410401801:234:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":235,"order":235,"actions":[{"uid":"410401801:235:1","speaker":"Kirito","text":"Damn it...!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可恶……！"},{"uid":"410401801:235:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:235:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":236,"order":236,"actions":[{"uid":"410401801:236:1","speaker":"Yuuki","text":"Isn't there anything we can do?","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"我们就没有什么可以做的吗？"},{"uid":"410401801:236:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":237,"order":237,"actions":[{"uid":"410401801:237:1","speaker":"Sinon","text":"I feel totally powerless...","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我感觉很无力……"},{"uid":"410401801:237:2","speaker":"Kirito","text":"","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:237:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":238,"order":238,"actions":[{"uid":"410401801:238:1","speaker":"Leafa","text":"If only we knew how to get them\nback home...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"如果我们知道如何让他们回家就好了……"},{"uid":"410401801:238:2","speaker":"Kirito","text":"","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":239,"order":239,"actions":[{"uid":"410401801:239:1","speaker":"Urdr","text":"...","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"..."}]},{"id":240,"order":240,"actions":[{"uid":"410401801:240:1","speaker":"Urdr","text":"Fairy warriors and foreign\nelements who lead this world\nto destruction...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"带领这个世界走向毁灭的仙女战士和外来元素……"}]},{"id":241,"order":241,"actions":[{"uid":"410401801:241:1","speaker":"Urdr","text":"The world has learned much from\nyour journey and has continued to\nsearch for new power and methods.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"世界从你的旅程中学到了很多，并继续寻找新的力量和方法。"}]},{"id":242,"order":242,"actions":[{"uid":"410401801:242:1","speaker":"Urdr","text":"Now it has learned of something\nelse. Foreign elements like you\nwere once considered anathema.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在它学到了别的东西。像你这样的外国分子曾经被视为令人厌恶的。"}]},{"id":243,"order":243,"actions":[{"uid":"410401801:243:1","speaker":"Urdr","text":"But, with enough time, it seems\nthat even you can be accommodated.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"不过，时间充裕的话，看来连你都可以容纳。"}]},{"id":244,"order":244,"actions":[{"uid":"410401801:244:1","speaker":"Kirito","text":"Wh-What are you saying?","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什、你在说什么？"},{"uid":"410401801:244:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:244:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":245,"order":245,"actions":[{"uid":"410401801:245:1","speaker":"Urdr","text":"Through the connection you have\nforged with the fairies, the world\nhas managed to trace...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"通过你与仙女们建立的联系，世界成功地追踪到了……"}]},{"id":246,"order":246,"actions":[{"uid":"410401801:246:1","speaker":"Urdr","text":"...the path of quantum circuits\nyou used to come here and to\nfind your original time stream.","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"...你曾经来这里并寻找你最初的时间流的量子电路路径。"}]},{"id":247,"order":247,"actions":[{"uid":"410401801:247:1","speaker":"Kirito","text":"What?! Then, you mean... you've\nfound a way for them to go home?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？！那么，你的意思是……你已经找到让他们回家的路了？！"},{"uid":"410401801:247:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:247:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":248,"order":248,"actions":[{"uid":"410401801:248:1","speaker":"Leafa","text":"Um, Urdr... I'm not sure that part\nabout quantum circuits actually\nmakes sense...","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"嗯，乌尔德...我不确定关于量子电路的部分是否真的有意义..."}]},{"id":249,"order":249,"actions":[{"uid":"410401801:249:1","speaker":"Sinon","text":"Don't ruin the moment, Leafa. I'm\npretty sure she's speaking on\nbehalf of Cardinal now.","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"别毁了这一刻，莉法。我很确定她现在代表卡迪纳尔发言。"},{"uid":"410401801:249:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401801:249:3","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":250,"order":250,"actions":[{"uid":"410401801:250:1","speaker":"Urdr","text":"This would not have happened\nwithout you and the fairies\nreaching an understanding...","pose":20330107,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"如果没有你和仙女们的谅解，这一切就不会发生……"}]},{"id":251,"order":251,"actions":[{"uid":"410401801:251:1","speaker":"Kirito","text":"So then... during the defrag,\nCardinal came to understand\nAlice and Eugeo as people?","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那么……在整理碎片的过程中，卡迪纳尔开始将爱丽丝和尤吉欧理解为人？"},{"uid":"410401801:251:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:251:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":252,"order":252,"actions":[{"uid":"410401801:252:1","speaker":"Asuna","text":"And that must have helped it find\na way back to their world!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这一定帮助它找到了回到自己世界的路！"},{"uid":"410401801:252:2","speaker":"Yuuki","text":"","pose":10050106,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":253,"order":253,"actions":[{"uid":"410401801:253:1","speaker":"Eugeo","text":"So... does this mean we can go\nhome?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"那……这是不是意味着我们可以回家了？"},{"uid":"410401801:253:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":254,"order":254,"actions":[{"uid":"410401801:254:1","speaker":"Alice","text":"Can we really trust you, Urdr?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"乌尔德，我们真的可以相信你吗？"},{"uid":"410401801:254:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":255,"order":255,"actions":[{"uid":"410401801:255:1","speaker":"Urdr","text":"Yes, foreign elements... Now that\nthe world understands you, you\nare no longer foreign.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"是的，外国元素……现在世界了解了你，你就不再是外国人了。"}]},{"id":256,"order":256,"actions":[{"uid":"410401801:256:1","speaker":"Urdr","text":"Now, come. There's no time to\nwaste. Both of you, take my hands.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在，来吧。没有时间可以浪费了。你们两个，握住我的手。"}]},{"id":257,"order":257,"actions":[{"uid":"410401801:257:1","speaker":"Kirito","text":"Eugeo, Alice...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧, 爱丽丝..."},{"uid":"410401801:257:2","speaker":"Sinon","text":"","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:257:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":258,"order":258,"actions":[{"uid":"410401801:258:1","speaker":"Eugeo","text":"Kirito... Everyone... Thank you.\nI guess this is goodbye...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人...大家...谢谢。我想这就是再见了……"},{"uid":"410401801:258:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":259,"order":259,"actions":[{"uid":"410401801:259:1","speaker":"Kirito","text":"I guess so... Oh, here, take this\nDivine Object with you. It should\nhelp you recover.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想是吧……哦，给，把这个神器带走吧。它应该可以帮助你康复。"},{"uid":"410401801:259:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:259:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":260,"order":260,"actions":[{"uid":"410401801:260:1","speaker":"Eugeo","text":"Ha ha, good idea. Okay, I'll take\nFenrir's Divine Object with me.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哈哈，好主意。好吧，我会带着芬里尔的神器一起去。"},{"uid":"410401801:260:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":261,"order":261,"actions":[{"uid":"410401801:261:1","speaker":"Alice","text":"Thank you for all your help.\nI know that we said we would\nnever forget one another...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"谢谢大家的帮助。我知道我们说过我们永远不会忘记彼此..."}]},{"id":262,"order":262,"actions":[{"uid":"410401801:262:1","speaker":"Alice","text":"But there's no telling what may\nhappen once we return to our\nown world.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是不知道回到自己的世界会发生什么。"}]},{"id":263,"order":263,"actions":[{"uid":"410401801:263:1","speaker":"Alice","text":"However... even if we do happen\nto forget you, I swear to you\nnow...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是……就算我们真的忘记了你，我现在也向你发誓……"}]},{"id":264,"order":264,"actions":[{"uid":"410401801:264:1","speaker":"Alice","text":"Should we see each other again,\nI shall be honored to greet you\nas comrades in arms.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果我们再次见面，我将很荣幸以战友的身份迎接你们。"}]},{"id":265,"order":265,"actions":[{"uid":"410401801:265:1","speaker":"Asuna","text":"Alice... The same goes for me too!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝...我也是这样！"},{"uid":"410401801:265:2","speaker":"Yuuki","text":"","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":266,"order":266,"actions":[{"uid":"410401801:266:1","speaker":"Kirito","text":"Absolutely. This isn't\nfarewell forever.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当然。这并不是永远的告别。"},{"uid":"410401801:266:2","speaker":"Sinon","text":"","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:266:3","speaker":"Leafa","text":"","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":267,"order":267,"actions":[{"uid":"410401801:267:1","speaker":"Kirito","text":"I'm sure that someday\nwe'll see each other again...\nTake care, you two.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"总有一天我们会再次见面的……你们两个保重。"},{"uid":"410401801:267:2","speaker":"Sinon","text":"","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":268,"order":268,"actions":[{"uid":"410401801:268:1","speaker":"Eugeo","text":"Thank you, Kirito, Asuna...\nAll of you... Thank you!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"谢谢桐人、亚丝娜...大家...谢谢！"},{"uid":"410401801:268:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":269,"order":269,"actions":[{"uid":"410401801:269:1","speaker":"Alice","text":"I promise that someday,\nwhen our worlds cross paths...\nWe shall meet again.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我保证，有一天，当我们的世界相遇时……我们会再次相遇。"}]},{"id":270,"order":270,"actions":[{"uid":"410401801:270:1","speaker":"Kirito","text":"You bet!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你敢打赌！"},{"uid":"410401801:270:2","speaker":"Sinon","text":"","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401801:270:3","speaker":"Leafa","text":"","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]}]};
